export function chaptersFor(locale: NotebookLocale): NotebookChapter[] {
  return chapters.filter((chapter) => chapter.locale === locale);
}

export function chapterBySlug(locale: NotebookLocale, slug: string): NotebookChapter | undefined {
  return chapters.find((chapter) => chapter.locale === locale && chapter.slug === slug);
}
